import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const marker =
  '<!-- Generated by pnpm skills:sync. Edit the canonical .agents skill; do not edit this copy. -->';

export async function syncSkills(root: string, check = false): Promise<number> {
  const canonicalRoot = resolve(root, '.agents/skills');
  const entries = (await readdir(canonicalRoot, { withFileTypes: true }))
    .filter((entry) => entry.isDirectory())
    .sort((a, b) => a.name.localeCompare(b.name));
  let count = 0;
  for (const entry of entries) {
    if (!/^[a-z][a-z0-9-]{0,63}$/.test(entry.name))
      throw new Error(`Invalid canonical skill name: ${entry.name}`);
    const source = await readFile(resolve(canonicalRoot, entry.name, 'SKILL.md'), 'utf8');
    const frontmatter = /^---\r?\n([\s\S]*?)\r?\n---\r?\n/.exec(source);
    if (
      !frontmatter ||
      !new RegExp(`^name: ${entry.name}$`, 'm').test(frontmatter[1]) ||
      !/^description: .+/m.test(frontmatter[1])
    )
      throw new Error(`Invalid skill frontmatter: ${entry.name}`);
    const generated = `${frontmatter[0]}\n${marker}\n\n${source.slice(frontmatter[0].length).trimStart()}`;
    const directory = resolve(root, '.claude/skills', entry.name);
    const target = resolve(directory, 'SKILL.md');
    const existing = await readFile(target, 'utf8').catch((error: NodeJS.ErrnoException) => {
      if (error.code === 'ENOENT') return null;
      throw error;
    });
    if (check) {
      if (existing !== generated)
        throw new Error(`Claude adapter is stale: ${entry.name}. Synchronize skills.`);
    } else {
      if (existing !== null && !existing.includes(marker))
        throw new Error(`Refusing to overwrite a non-generated Claude skill: ${entry.name}`);
      await mkdir(directory, { recursive: true });
      await writeFile(target, generated);
    }
    count++;
  }
  const adapters = await readdir(resolve(root, '.claude/skills'), { withFileTypes: true }).catch(
    (error: NodeJS.ErrnoException) => {
      if (error.code === 'ENOENT') return [];
      throw error;
    },
  );
  const names = new Set(entries.map((entry) => entry.name));
  for (const adapter of adapters) {
    if (!adapter.isDirectory() || names.has(adapter.name)) continue;
    const source = await readFile(
      resolve(root, '.claude/skills', adapter.name, 'SKILL.md'),
      'utf8',
    ).catch(() => '');
    if (source.includes(marker))
      throw new Error(
        `Obsolete generated Claude adapter: ${adapter.name}. Remove it with its retired canonical skill.`,
      );
  }
  return count;
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  const unknown = process.argv.slice(2).filter((argument) => argument !== '--check');
  if (unknown.length) throw new Error('Usage: pnpm skills:sync [--check]');
  const count = await syncSkills(process.cwd(), process.argv.includes('--check'));
  console.log(
    `${process.argv.includes('--check') ? 'Checked' : 'Synchronized'} ${count} skill adapters.`,
  );
}
